from mk import *
from lib import fbd
STRICT["on"] = True
import math

def fig():
    g = Fig(560, 200, "קרונית במסה 0.6 קילוגרם נעה ימינה במהירות 2 מטר לשנייה על מסילה אופקית חסרת חיכוך. מתחת לקרונית מודבק כדור במסה 0.2 קילוגרם. ציר x לאורך המסילה וציר y כלפי מטה, וראשית הצירים במקום הכדור ברגע t=0")
    g.rect(140, 40, 180, 40, fill="none", width=2)
    for x in (165, 295): g.circle(x, 86, 7, fill="none", stroke="var(--d-line)")
    g.line(60, 93, 500, 93, width=2)
    g.arrow(300, 26, 360, 26, "v = 2 m/s", lx=368, ly=30, anchor="start")
    g.circle(230, 98, 6, fill="var(--d-body)")
    g.add('<line x1="230" y1="98" x2="460" y2="98" stroke="var(--d-dim)" stroke-width="1.2" marker-end="url(#f-axis)"/>'); g.text(466, 102, "x", anchor="start")
    g.add('<line x1="230" y1="98" x2="230" y2="190" stroke="var(--d-dim)" stroke-width="1.2" marker-end="url(#f-axis)"/>'); g.text(240, 190, "y", anchor="start")
    return g

E(id="bagrut-2006-q3", year=2006, label="2006 שאלה 3", topic="momentum", sub="mom-conservation", diff=3, fig=fig,
  stem=r"קרונית שמסתה $0.6\,\text{kg}$ נוסעת ימינה במהירות קבועה $2\,\text{m/s}$ על מסילה אופקית בלי חיכוך. המסילה נמצאת בגובה מסוים מעל הרצפה, ויש לה שני פסים עם רווח ביניהם. ציר $x$ הוא לאורך המסילה, והכיוון החיובי שלו הוא כיוון הנסיעה. ציר $y$ אנכי, והכיוון החיובי שלו כלפי מטה. ברגע $t = 0$ הקרונית עוברת בראשית הצירים. כדור שמסתו $0.2\,\text{kg}$ היה מודבק מבחוץ לתחתית הקרונית. ברגע $t = 0$ הכדור ניתק מהקרונית, נפל נפילה חופשית ועבר ברווח שבין פסי המסילה. מזניחים את התנגדות האוויר.",
  parts=[
    P("א", r"האם מהירות הקרונית השתנתה כשהכדור ניתק ממנה? הסבירו.", choice(["השתנתה", "לא השתנתה"], 1), ["principle"], [
        S(r"שימור תנע בציר x", r"הכדור ניתק בלי דחיפה, ולכן הוא ממשיך באותה מהירות אופקית כמו הקרונית. הוא לא לוקח מהקרונית תנע", r"0.8 \cdot 2 = 0.6\,V + 0.2 \cdot 2 \;\Rightarrow\; V = 2\,\text{m/s}", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
    ], r"לא השתנתה", key=r"לא השתנתה"),
    P("ב1", r"מה שיעור ה-$x$ של הקרונית ברגע $t = 1\,\text{s}$? מזניחים את גודל הקרונית.", num(2, "m"), ["principle"], [
        S(r"מהירות קבועה", r"מהירות הקרונית לא השתנתה", r"x = 0 + 2 \cdot 1 = 2\,\text{m}", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
    ], r"$2\,\text{m}$", key=r"x=2 m"),
    P("ב2", r"מה שיעורי ה-$x$ וה-$y$ של הכדור ברגע $t = 1\,\text{s}$? כתבו את שיעור ה-$y$.", num(5, "m"), ["principle"], [
        S(r"בציר x", r"לכדור אותה מהירות אופקית כמו לקרונית", r"x = 0 + 2 \cdot 1 = 2\,\text{m}", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
        S(r"בציר y", r"נפילה חופשית בלי מהירות התחלתית אנכית. ציר y כלפי מטה, ולכן התאוצה חיובית", r"y = 0 + 0 + \tfrac{1}{2} \cdot 10 \cdot 1^2 = 5\,\text{m}"),
    ], r"$(x,\ y) = (2,\ 5)\,\text{m}$", key=r"x=2 m ; y=5 m"),
    P("ב3", r"מה המהירות של הכדור (גודל וכיוון) ברגע $t = 1\,\text{s}$?", multi((r"גודל המהירות", math.hypot(2, 10), "m/s"), (r"הזווית מתחת לאופק", math.degrees(math.atan(10 / 2)), "°")), ["principle"], [
        S(r"הרכיבים", r"הרכיב האופקי לא משתנה. הרכיב האנכי גדל בתאוצת הכובד", r"v_x = 2\,\text{m/s},\qquad v_y = 0 + 10 \cdot 1 = 10\,\text{m/s}", eq=r"v = v_0 + at"),
        S(r"הגודל", r"לפי משפט פיתגורס", r"v = \sqrt{2^2 + 10^2} = \sqrt{104} \approx 10.2\,\text{m/s}"),
        S(r"הכיוון", r"הטנגנס של הזווית מתחת לאופק הוא הרכיב האנכי חלקי האופקי", r"\tan\alpha = \frac{10}{2} = 5 \;\Rightarrow\; \alpha \approx 78.7^\circ"),
    ], r"$\approx 10.2\,\text{m/s}$, בזווית $\approx 78.7^\circ$ מתחת לאופק", key=r"≈10.2 m/s ; α=78.7°"),
    P("ג", r"כדור נוסף, זהה לראשון, נשמט ממנוחה ברגע מאוחר מ-$t = 1\,\text{s}$, מנקודה מעל המסילה. הוא נופל נפילה חופשית, פוגע בקרונית הנוסעת ונדבק אליה. האם מהירות הקרונית השתנתה? אם לא, נמקו. אם כן, מה מהירות הקרונית עם הכדור?", num(1.5, "m/s"), ["principle"], [
        S(r"שימור תנע בציר x", r"לכדור הנופל אין תנע אופקי, והמסה שנעה גדלה. את התנע האנכי בולמת המסילה", r"0.6 \cdot 2 + 0.2 \cdot 0 = (0.6 + 0.2)\,V'", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
        S(r"פותרים", r"מחלקים במסה הכוללת", r"V' = \frac{1.2}{0.8} = 1.5\,\text{m/s}"),
    ], r"השתנתה: $1.5\,\text{m/s}$", key=r"מהירות הקרונית השתנתה"),
  ],
  concepts=["שימור תנע אופקי", "גוף שמשתחרר מגוף נע", "זריקה אופקית", "התנגשות פלסטית"],
  summary=r"כדור שנופל מקרונית לא משנה את המהירות שלה. כדור שנופל לתוכה כן.",
  review="הנחה שלי.\nבסעיף ב3 שתי תיבות: גודל המהירות והזווית.\nמה לבדוק: רק לאשר.")
